// === Tab: mySketch ===
let vs = `
   precision highp float;
   precision highp int;

   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   varying vec2 vTexCoord;
   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;

    void main() {
      vec4 positionVec4 = vec4(aPosition, 1.0);
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
      vTexCoord = aTexCoord;
   }
`;

let fs = `
   precision highp float;
   precision highp int;

   varying vec2 vTexCoord;

   uniform sampler2D u_tex;
   uniform float u_time;
   uniform vec3 u_color0;
   uniform vec3 u_color1;
   uniform vec3 u_color2;
   uniform vec3 u_color3;

   float pi = 3.14159265358979;

   void main() {
      vec3 c0 = mix(u_color0, u_color1, vTexCoord.y);
      vec3 c1 = mix(u_color2, u_color3, vTexCoord.y);
      vec3 color = mix(c0, c1, vTexCoord.x);

      vec2 uv = vTexCoord;
      uv.x += 0.2*cos( pi*cos(-uv.y*pi*3.0 + u_time)  ) ;
      uv.y += 0.1*sin( pi*sin(-uv.x*pi*2.0 + u_time)  ) ;
      vec4 tex = texture2D(u_tex, uv);

      float mask = 3.0*exp2(-1.0*pow((2.0*vTexCoord.x-1.0), 2.0)/0.2) * exp2(-1.0*pow((2.0*vTexCoord.y-1.0), 2.0)/0.2);
      mask = min(mask, 1.0);

      gl_FragColor = vec4(color, 0.8) * tex * mask ;
    }
`;

const w = 1112;
let theShader ;
let pg;
let color0, color1, color2, color3;

function setup() {
   setAttributes("alpha", false);
   setAttributes("antialias", true);
   setAttributes("powerPreference", "high-performance");

   createCanvas(w, w*.75, WEBGL);

   rectMode(CENTER);
   imageMode(CENTER);
   textureMode(NORMAL);
   colorMode(HSB);
   noStroke();

   theShader = createShader(vs, fs);
   color0 = rand_color();
   color1 = rand_color();
   color2 = rand_color();
   color3 = rand_color();

   pg = createGraphics(w/2, w/2);
   pg.rectMode(CENTER);
}

function draw(){
   set_graphics();

   background(100);
   fill(0, 0, 0, 0);

   shader(theShader);
   theShader.setUniform(`u_tex`, pg);
   theShader.setUniform(`u_time`, -frameCount/30);
   theShader.setUniform(`u_color0`, color0);
   theShader.setUniform(`u_color1`, color1);
   theShader.setUniform(`u_color2`, color2);
   theShader.setUniform(`u_color3`, color3);

   rect(0, 0, w*1.2, w*1.2);
   box(w*0.3);
   box(w*0.5);
}

function rand_color() {
   let rc = color(random(100,360), random(70, 100), random(90, 100));
   return [red(rc)/255.0, green(rc)/255.0, blue(rc)/255.0];
}

function set_graphics(){
   const pgw = pg.width/2 ;
   const pgr = pg.width/4 * 0.8 ;
   let px, py;
   pg.background(180);
   pg.stroke(255);
   pg.fill(255);
   pg.rect(pgw, pgw, pgr, pgr);

   pg.noFill();
   pg.strokeWeight(5);

   for(let i=0;i<40;i++){
    px = 30*sin(i+frameCount/50) + pgw + pgw*0.7*cos(frameCount/40 + PI/10*i);
    py = 30*sin(i+frameCount/50) + pgw + pgw*0.7*sin(frameCount/40 + PI/10*i);
    pg.rect(px, py,  0.3*pgr, 0.3*pgr);
   }

}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + day() + hour() + minute() + second() + ".png");
    lapse = millis();
  }
}

